const b = $json.body || $json;
const parseAddr = (s='') => {
  const m = String(s).match(/^\s*"?([^"<]*?)"?\s*<([^>]+)>\s*$/);
  if (m) return {name: m[1].trim(), email: m[2].trim().toLowerCase()};
  return {name: '', email: String(s).trim().toLowerCase()};
};
const dom = e => (e.split('@')[1] || '').toLowerCase();
const from = parseAddr(b.from || '');
const reply = b.replyTo ? parseAddr(b.replyTo) : null;
const fromDomain = dom(from.email);
const replyDomain = reply ? dom(reply.email) : '';
const text = String(b.body || '');
const attachments = Array.isArray(b.attachments) ? b.attachments : [];
const urls = [...new Set((text.match(/https?:\/\/[^\s<>"')]+/gi) || []).map(u => u.replace(/[.,;]+$/, '')))];
const defang = u => String(u).replace(/^http/i, 'hxxp').replace(/\./g, '[.]');
const host = u => { try { return new URL(u).hostname.toLowerCase(); } catch (e) { return ''; } };

const BRANDS = {
  paypal: ['paypal.com'], microsoft: ['microsoft.com','office.com','outlook.com','live.com','microsoftonline.com'],
  amazon: ['amazon.com','amazon.in'], google: ['google.com','gmail.com','accounts.google.com'],
  apple: ['apple.com','icloud.com'], netflix: ['netflix.com'], github: ['github.com'],
  hdfc: ['hdfcbank.com','hdfcbank.net'], sbi: ['sbi.co.in','onlinesbi.sbi'], dhl: ['dhl.com'], linkedin: ['linkedin.com']
};
const SUS_TLD = ['zip','top','xyz','click','country','gq','tk','ml','cf','work','support','rest','icu','buzz'];
const SHORT = ['bit.ly','tinyurl.com','t.co','goo.gl','is.gd','cutt.ly','rb.gy','shorturl.at'];
const BAD_EXT = ['exe','scr','js','vbs','bat','cmd','lnk','iso','jar','hta','docm','xlsm','html','htm'];
const isLegit = (h, list) => list.some(d => h === d || h.endsWith('.' + d));
const norm = s => s.toLowerCase().replace(/0/g,'o').replace(/1/g,'l').replace(/rn/g,'m').replace(/vv/g,'w').replace(/5/g,'s').replace(/3/g,'e').replace(/[-_]/g,'');
const lev = (a, b2) => { const d = Array.from({length:a.length+1}, (_,i)=>[i]); for (let j=1;j<=b2.length;j++) d[0][j]=j;
  for (let i=1;i<=a.length;i++) for (let j=1;j<=b2.length;j++) d[i][j]=Math.min(d[i-1][j]+1,d[i][j-1]+1,d[i-1][j-1]+(a[i-1]===b2[j-1]?0:1)); return d[a.length][b2.length]; };
const lookalike = h => {
  const out = [];
  if (!h) return out;
  const labels = h.split('.'); const sld = labels.length >= 2 ? labels[labels.length-2] : h;
  for (const [brand, legit] of Object.entries(BRANDS)) {
    if (isLegit(h, legit)) continue;
    const n = norm(h), ns = norm(sld);
    if (ns === brand) out.push(`${h} is a homoglyph of "${brand}"`);
    else if (n.includes(brand)) out.push(`${h} embeds brand "${brand}" but is not an official domain`);
    else if (brand.length >= 5 && lev(ns, brand) <= 1) out.push(`${h} is 1 edit away from "${brand}"`);
  }
  return out;
};

const flags = [];
// 1. display name vs sender domain
const dn = from.name.toLowerCase();
for (const [brand, legit] of Object.entries(BRANDS)) {
  if (dn.includes(brand) && !isLegit(fromDomain, legit)) flags.push(`Display name "${from.name}" claims ${brand} but sender domain is ${fromDomain}`);
}
// 2. reply-to mismatch
if (reply && replyDomain && replyDomain !== fromDomain) flags.push(`Reply-To domain (${replyDomain}) differs from From domain (${fromDomain})`);
// 3. look-alike domains (sender + links)
lookalike(fromDomain).forEach(x => flags.push('Sender look-alike: ' + x));
const hosts = [...new Set(urls.map(host).filter(Boolean))];
hosts.forEach(h => lookalike(h).forEach(x => flags.push('Link look-alike: ' + x)));
// 4. link heuristics
hosts.forEach(h => {
  if (/^\d{1,3}(\.\d{1,3}){3}$/.test(h)) flags.push(`Link uses raw IP address (${h})`);
  if (SHORT.includes(h)) flags.push(`URL shortener used (${h})`);
  if (h.includes('xn--')) flags.push(`Punycode domain (${h})`);
  if (SUS_TLD.includes(h.split('.').pop())) flags.push(`Suspicious TLD on link (${h})`);
});
if (SUS_TLD.includes(fromDomain.split('.').pop())) flags.push(`Suspicious TLD on sender (${fromDomain})`);
if (fromDomain && hosts.length && !hosts.some(h => h === fromDomain || h.endsWith('.'+fromDomain) || fromDomain.endsWith('.'+h)))
  flags.push('No link points to the sender domain');
// 5. attachments
attachments.forEach(a => {
  const ext = String(a).toLowerCase().split('.').pop();
  if (/\.\w{2,4}\.(exe|scr|js|bat|cmd|vbs|lnk)$/i.test(a)) flags.push(`Double-extension attachment: ${a}`);
  else if (BAD_EXT.includes(ext)) flags.push(`Risky attachment type: ${a}`);
});
// 6. language cues
if (/urgent|immediately|within \d+ ?(hours|hrs)|suspend|verify your|confirm your|account (is )?(limited|locked)|password/i.test(text + ' ' + (b.subject||''))) flags.push('Urgency / credential-harvesting language');
if (/unsubscribe|% ?off|winner|lottery|limited[- ]time|sale ends|free gift/i.test(text + ' ' + (b.subject||''))) flags.push('Bulk-marketing language');

// dedupe key (stable per email)
const keySrc = String(b.messageId || (b.from + '|' + b.subject + '|' + b.date));
let h = 5381; for (let i = 0; i < keySrc.length; i++) h = ((h << 5) + h + keySrc.charCodeAt(i)) >>> 0;
const dedupeKey = 'ngp033-' + h.toString(16);

const analysis = {
  messageId: b.messageId || null, from: b.from, fromName: from.name, fromEmail: from.email, fromDomain,
  replyTo: b.replyTo || null, replyDomain, subject: b.subject || '', date: b.date || null,
  attachments, linkDomains: hosts, urls, flags, bodyExcerpt: text.slice(0, 1500)
};
return { json: { dedupeKey, ...analysis, urlsDefanged: urls.map(defang), llmInput: JSON.stringify(analysis, null, 2) } };

const a = $('Extract & Flag').item.json;
let raw = String($json.output ?? $json.text ?? '').replace(/```json|```/g, '').trim();
let r;
try { r = JSON.parse(raw.slice(raw.indexOf('{'), raw.lastIndexOf('}') + 1)); }
catch (e) { r = {verdict:'unknown', confidence:0, severity:'MEDIUM', summary:'AI output unparseable - manual review needed', reasons:[raw.slice(0,200)]}; }
const verdict = String(r.verdict || 'unknown').toLowerCase();
const sevMap = {phish:'HIGH', spam:'LOW', legit:'INFO'};
const severity = String(r.severity || sevMap[verdict] || 'MEDIUM').toUpperCase();
const icon = {phish:'\u{1F534}', spam:'\u{1F7E1}', legit:'\u{1F7E2}'}[verdict] || '\u26AA';
const esc = s => String(s ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const ist = new Date().toLocaleString('en-GB', {timeZone:'Asia/Kolkata', hour12:false}) + ' IST';
const header = `\u{1F7E3} NGP-033 | exec #${$execution.id} | ${ist} | ${verdict.toUpperCase()} / ${severity} | ${r.summary}`;

const evidence = [...(r.reasons || []).map(x => '\u2022 ' + esc(x)), ...a.flags.map(x => '\u2022 [rule] ' + esc(x))];
const lines = [
  `<b>${esc(header)}</b>`, '',
  `${icon} <b>Verdict:</b> ${esc(verdict.toUpperCase())} (confidence ${esc(r.confidence)})`,
  `<b>From:</b> ${esc(a.from)}`,
  `<b>Reply-To:</b> ${esc(a.replyTo || '-')}`,
  `<b>Subject:</b> ${esc(a.subject)}`, '',
  '<b>Evidence:</b>', ...(evidence.length ? evidence : ['\u2022 none']), '',
  '<b>Links (defanged):</b>', ...(a.urlsDefanged.length ? a.urlsDefanged.map(u => '\u2022 <code>' + esc(u) + '</code>') : ['\u2022 none']), '',
  '<b>Attachments:</b> ' + (a.attachments.length ? a.attachments.map(x => '<code>' + esc(String(x).replace(/\./g,'[.]')) + '</code>').join(', ') : 'none')
];
return { json: { message: lines.join('\n').slice(0, 3900), verdict, severity, dedupeKey: a.dedupeKey } };

const sd = $getWorkflowStaticData('global');
sd.blocked = sd.blocked || [];
const m = $json.message || {};
const entry = { ts: new Date().toISOString(), fromId: m.from?.id, username: m.from?.username || null, chatId: m.chat?.id, textLength: (m.text || '').length };
sd.blocked.push(entry);
if (sd.blocked.length > 200) sd.blocked.shift();
console.warn('NGP-033 BLOCKED inbound Telegram message (not in allowlist): ' + JSON.stringify(entry));
return { json: { blocked: true, ...entry, totalBlocked: sd.blocked.length } };
